def rectangles_overlap(r1, r2):
    # Check if the interiors overlap
    if r1 == r2:
        return False
    if r1[0] > r2[2] or r1[2] < r2[0]:
        return False
    if r1[1] > r2[1] or r1[3] < r2[1]:
        return False
    return True
