def rectangle_intersection_area(r1, r2):
    # Find intersection points
    x1 = max(r1[0], r2[0])
    x2 = min(r1[2], r2[2])
    y1 = max(r1[1], r2[1])
    y2 = min(r1[3], r2[3])

    # Check if the rectangles overlap
    if x1 <= x2 and y1 <= y2:
        return (x2 - x1) * (y2 - y1)
    else:
        return 0
